#include <Servo.h>

Servo myServo;          // Создаем объект для управления сервоприводом
const int trigPin = 9;  // Пин Trig ультразвукового датчика
const int echoPin = 8;  // Пин Echo ультразвукового датчика
const int servoPin = 10;// Пин сигнала сервопривода (оранжевый/желтый провод)

// Настройки расстояния и углов поворота
const int openDistance = 20; // Срабатывать, если рука ближе 20 см
const int closeAngle = 0;    // Угол сервопривода при закрытой крышке (0 градусов)
const int openAngle = 90;    // Угол сервопривода при открытой крышке (90 градусов)

void setup() {
  myServo.attach(servoPin);
  myServo.write(closeAngle); // При старте устанавливаем крышку в закрытое положение

  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
}

void loop() {
  // Измеряем расстояние с помощью ультразвука
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  long duration = pulseIn(echoPin, HIGH);
  int distance = duration * 0.034 / 2; // Переводим время задержки в сантиметры

  // Если рука ближе 20 см
  if (distance > 0 && distance <= openDistance) {
    myServo.write(openAngle); // Открываем крышку
    delay(3000);              // Держим открытой 3 секунды
    myServo.write(closeAngle);// Закрываем крышку
  }

  delay(100); // Небольшая пауза между замерaми
}
